import type { ObjectId } from "mongodb";
import type { WeeklySummaryReport } from "../../interfaces/weeklySummaryReport.interface";
import { getWeeklySummaryReportCollection } from "../../models/weeklySummaryReport.model";

export interface SaveReportInput {
  groupWhatsappId: string;
  periodStart: Date;
  periodEnd: Date;
  content: string;
  model: string;
}

/**
 * Service responsible for persisting the weekly reports generated by Gemini.
 *
 * A report is saved BEFORE it is sent to WhatsApp, so a failed delivery
 * never loses an already-paid Gemini call.
 */
export class WeeklySummaryReportService {
  /**
   * Saves a freshly generated report as not-yet-delivered.
   *
   * @returns The inserted document id, to be passed to `markDelivered`.
   */
  async save(input: SaveReportInput): Promise<ObjectId> {
    const result = await getWeeklySummaryReportCollection().insertOne({
      ...input,
      delivered: false,
      deliveredAt: null,
      generatedAt: new Date(),
    });

    return result.insertedId;
  }

  /**
   * Marks a report as delivered to the WhatsApp group.
   *
   * @param id - Id returned by `save`.
   */
  async markDelivered(id: ObjectId): Promise<void> {
    await getWeeklySummaryReportCollection().updateOne(
      { _id: id },
      { $set: { delivered: true, deliveredAt: new Date() } },
    );
  }

  /**
   * Returns the most recent report of a group, or null if none exists.
   *
   * @param groupWhatsappId - WhatsApp group identifier.
   */
  async findLatest(
    groupWhatsappId: string,
  ): Promise<WeeklySummaryReport | null> {
    return getWeeklySummaryReportCollection().findOne(
      { groupWhatsappId },
      { sort: { generatedAt: -1 } },
    );
  }

  /**
   * Returns the latest reports of a group, newest first.
   *
   * @param groupWhatsappId - WhatsApp group identifier.
   * @param limit - Maximum number of reports. Defaults to 10.
   */
  async findHistory(
    groupWhatsappId: string,
    limit = 10,
  ): Promise<WeeklySummaryReport[]> {
    return getWeeklySummaryReportCollection()
      .find({ groupWhatsappId })
      .sort({ generatedAt: -1 })
      .limit(limit)
      .toArray();
  }
}
